    """Build results JSONB structure by combining analysis JSON and available files."""
    results_root = Path("../results")
    analysis_root = Path("../analysis")

    analysis_data, analysis_path = load_analysis_results(elab_id)

    # Base structure
    now_iso = datetime.now(timezone.utc).isoformat()
    results = {
