        "message": "",
        "timestamp": now_iso,
        "summary": {},
        "metadata": {},
        "warnings": [],
        "data_files": {},
        "plots": {}
    }

    if analysis_data is not None:
        # Map status and message
        status = analysis_data.get("status", "failed")
        results["analysis_status"] = status
        results["message"] = analysis_data.get("message", "")
        # Copy metadata and warnings
        if isinstance(analysis_data.get("metadata"), dict):
            results["metadata"] = analysis_data["metadata"]
        if isinstance(analysis_data.get("warnings"), list):
            results["warnings"] = analysis_data["warnings"]
        # Summary metrics
        summary = {}
        if "files_processed" in analysis_data:
            summary["files_processed"] = analysis_data.get("files_processed")
        md = analysis_data.get("metadata") or {}
        if isinstance(md, dict):
            for k_src, k_dst in [
                ("num_ligand_concentrations", "num_ligand_concentrations"),
                ("num_salt_concentrations", "num_salt_concentrations"),
                ("replicates", "replicates"),
            ]:
                if k_src in md:
                    summary[k_dst] = md[k_src]
        results["summary"] = summary

        # Data files from analysis JSON
        data_outputs = analysis_data.get("data_outputs", {}) or {}
        if isinstance(data_outputs, dict):
            if "tecan_raw_excel" in data_outputs:
                results["data_files"]["tecan_raw_excel"] = data_outputs["tecan_raw_excel"]
            if "per_well_csv" in data_outputs:
                results["data_files"]["per_well_csv"] = data_outputs["per_well_csv"]
            if "aggregated_isotherm_csv" in data_outputs:
                results["data_files"]["aggregated_isotherm_csv"] = data_outputs["aggregated_isotherm_csv"]
