def parse_numeric(value):
    """Extract a numeric value from a string like '25 °C' or '100 mM'.

    Call this ONLY for a single-valued field eLabFTW types as a number. On a text field
    it is destructive - '20 mM NaAc' becomes 20.0 and the buffer identity is gone - and
    on a delimited list it keeps only the first element. When in doubt, store the
    original string unchanged.
    """
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        text = value.strip()
        import re

        # If the whole string looks like a single number (allowing comma decimal)
        m_full = re.fullmatch(r"[-+]?\d{1,3}(?:[.,]\d+)?", text)
        if m_full:
            return float(text.replace(",", "."))
        # Otherwise, extract first float-like substring
        match = re.search(r"[-+]?\d*\.?,?\d+", text)
        if match:
            num_str = match.group(0).replace(",", ".")
            try:
                return float(num_str)
            except ValueError:
                return None
    return None


def parse_field(value, field_type=None):
    """Route an eLabFTW value by what it IS, not by which parameter it came from.

    Any field may arrive as a delimited list, so the delimiter check comes first.
    """
    if value is None or value == "":
        return None
    if isinstance(value, (list, int, float)):
        return value
    text = str(value).strip()
    # a list if a delimiter separates more than one token; "1,5" (decimal comma) is one
    for sep in (";", ","):
        parts = [p.strip() for p in text.split(sep) if p.strip()]
        if len(parts) > 1:
            # Check if this is actually a decimal comma case (single numeric token)
            if sep == "," and len(parts) == 2:
                joined = "".join(parts)
                try:
                    return float(joined)
                except ValueError:
                    pass
            # Try to parse all parts as floats
            try:
                return [float(p.replace(",", ".")) for p in parts]
            except ValueError:
                return parts
    if field_type == "number":
        num = parse_numeric(text)
        return num if num is not None else text
    return text


def find_experiment_json(elab_id):
    """Find experiment JSON file."""
    paths = [
        Path(f"../experiment_{elab_id}.json"),
        Path(f"../data/experiment_{elab_id}.json"),
    ]
    for p in paths:
        if p.exists():
            return p
    raise FileNotFoundError(f"Experiment JSON not found for {elab_id}")


def load_workflow():
    """Load workflow.json and extract lab_id."""
    workflow_path = Path("../workflow.json")
    if workflow_path.exists():
        with open(workflow_path) as f:
            data = json.load(f)
            return data, data.get("lab_id") or data.get("labId")
    return None, None


def extract_metadata(extra_fields):
    """Extract and map metadata from eLabFTW extra fields.

    Respects eLabFTW field types and possible list values.
    """
    metadata = {}
    for elab_name, db_name in FIELD_MAPPING.items():
        if elab_name not in extra_fields:
            continue
        field = extra_fields.get(elab_name, {})
        value = field.get("value")
        field_type = field.get("type")  # 'text', 'number', etc.
        parsed = parse_field(value, field_type=field_type)
        metadata[db_name] = parsed
    return metadata


def list_folder_files(folder_path):
    """List files in a folder."""
    folder = Path(folder_path)
    if folder.exists():
        return [f.name for f in folder.iterdir() if f.is_file()]
    return []


def build_raw_data(elab_id):
    """Build raw_data JSONB structure."""
    data_folder = Path("../data")
    return {
        "folder_path": str(data_folder.resolve()),
        "files": list_folder_files(data_folder),
    }


def load_analysis_results(elab_id):
    """Load the main analysis results JSON produced by the analysis script, if present."""
    candidates = [
        Path("../results") / f"analysis_results_{elab_id}.json",
        Path("../analysis") / f"analysis_results_{elab_id}.json",
    ]
    for p in candidates:
        if p.exists():
            try:
                with open(p, "r") as f:
                    data = json.load(f)
                return data, p
            except Exception:
                continue
    return None, None


def build_results(elab_id):
    """Build results JSONB structure by combining analysis JSON and available files."""
    results_root = Path("../results")
    analysis_root = Path("../analysis")

    analysis_data, analysis_path = load_analysis_results(elab_id)

    # Base structure
    now_iso = datetime.now(timezone.utc).isoformat()
    results = {
        "analysis_status": "pending",
        "message": "",
        "timestamp": now_iso,
        "summary": {},
        "metadata": {},
        "warnings": [],
        "data_files": {},
        "plots": {},
    }

    if analysis_data is not None:
        # Map status and message
        status = analysis_data.get("status", "failed")
        results["analysis_status"] = status
        results["message"] = analysis_data.get("message", "")
        # Copy metadata and warnings
        if isinstance(analysis_data.get("metadata"), dict):
            results["metadata"] = analysis_data["metadata"]
        if isinstance(analysis_data.get("warnings"), list):
            results["warnings"] = analysis_data["warnings"]
        # Summary metrics
        summary = {}
        if "files_processed" in analysis_data:
            summary["files_processed"] = analysis_data.get("files_processed")
        md = analysis_data.get("metadata") or {}
        if isinstance(md, dict):
            for k_src, k_dst in [
                ("num_ligand_concentrations", "num_ligand_concentrations"),
                ("num_salt_concentrations", "num_salt_concentrations"),
                ("replicates", "replicates"),
            ]:
                if k_src in md:
                    summary[k_dst] = md[k_src]
        results["summary"] = summary

        # Data files from analysis JSON
        data_outputs = analysis_data.get("data_outputs", {}) or {}
        if isinstance(data_outputs, dict):
            if "tecan_raw_excel" in data_outputs:
                results["data_files"]["tecan_raw_excel"] = data_outputs[
                    "tecan_raw_excel"
                ]
            if "per_well_csv" in data_outputs:
                results["data_files"]["per_well_csv"] = data_outputs["per_well_csv"]
            if "aggregated_isotherm_csv" in data_outputs:
                results["data_files"]["aggregated_isotherm_csv"] = data_outputs[
                    "aggregated_isotherm_csv"
                ]
            if "langmuir_fits_csv" in data_outputs:
                results["data_files"]["langmuir_fits_csv"] = data_outputs[
                    "langmuir_fits_csv"
                ]

        # Plots from analysis JSON
        plots = analysis_data.get("plots", {}) or {}
        if isinstance(plots, dict):
            if "loading_isotherms_png" in plots:
                results["plots"]["loading_isotherms_png"] = plots[
                    "loading_isotherms_png"
                ]
            if "loading_isotherms_pdf" in plots:
                results["plots"]["loading_isotherms_pdf"] = plots[
                    "loading_isotherms_pdf"
                ]

        # Include path to the analysis JSON itself
        if analysis_path is not None:
            results["data_files"]["analysis_results_json"] = str(
                analysis_path.resolve()
            )
    else:
        # No analysis JSON found; still list whatever files are present
        results["analysis_status"] = "pending"
        results[
            "message"
        ] = "Analysis results JSON not found; only file listing recorded."

    # Also scan results/ and analysis/ folders for matching filenames as a fallback
    def add_if_exists(root: Path, pattern: str, key: str, container: dict):
        p = root / pattern
        if p.exists():
            container[key] = str(p.resolve())

    add_if_exists(
        results_root,
        f"analysis_results_{elab_id}.json",
        "analysis_results_json",
        results["data_files"],
    )
    add_if_exists(
        results_root,
        f"per_well_data_{elab_id}.csv",
        "per_well_csv",
        results["data_files"],
    )
    add_if_exists(
        results_root,
        f"aggregated_isotherm_data_{elab_id}.csv",
        "aggregated_isotherm_csv",
        results["data_files"],
    )
    add_if_exists(
        results_root,
        f"langmuir_fits_{elab_id}.csv",
        "langmuir_fits_csv",
        results["data_files"],
    )
    add_if_exists(
        results_root,
        f"tecan_data_{elab_id}.xlsx",
        "tecan_raw_excel",
        results["data_files"],
    )

    add_if_exists(
        results_root,
        f"loading_isotherms_{elab_id}.png",
        "loading_isotherms_png",
        results["plots"],
    )
    add_if_exists(
        results_root,
        f"loading_isotherms_{elab_id}.pdf",
        "loading_isotherms_pdf",
        results["plots"],
    )

    return results


# ============================================================================
# MAIN FUNCTIONS
# ============================================================================


def upsert_process_schema(cursor):
    """Insert or update process schema."""
    cursor.execute(
        """
        INSERT INTO process_schemas (
            process_id, process_name, version,
            metadata_schema, results_schema, field_mapping, expected_files
        ) VALUES (%s, %s, %s, %s, %s, %s, %s)
        ON CONFLICT (process_id) DO UPDATE SET
            process_name = EXCLUDED.process_name,
            metadata_schema = EXCLUDED.metadata_schema,
            results_schema = EXCLUDED.results_schema,
            field_mapping = EXCLUDED.field_mapping,
            expected_files = EXCLUDED.expected_files,
            updated_at = NOW()
    """,
        (
            PROCESS_ID,
            PROCESS_NAME,
            PROCESS_VERSION,
            json.dumps(METADATA_SCHEMA),
            json.dumps(RESULTS_SCHEMA),
            json.dumps(FIELD_MAPPING),
            json.dumps(EXPECTED_FILES),
        ),
    )


def upsert_experiment(cursor, elab_id, data):
    """Insert or update experiment execution."""
    cursor.execute(
        """
        INSERT INTO experiment_executions (
            elab_id, elab_title, process_id, process_name, lab_id,
            status, "user", workflow_json, metadata, raw_data, results
        ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        ON CONFLICT (elab_id) DO UPDATE SET
            elab_title = EXCLUDED.elab_title,
            status = EXCLUDED.status,
            metadata = EXCLUDED.metadata,
            raw_data = EXCLUDED.raw_data,
            results = EXCLUDED.results,
            workflow_json = EXCLUDED.workflow_json,
            updated_at = NOW()
        RETURNING id
    """,
        (
            elab_id,
            data["title"],
            PROCESS_ID,
            PROCESS_NAME,
            data["lab_id"],
            data["status"],
            data["user"],
            json.dumps(data["workflow_json"]) if data["workflow_json"] else None,
            json.dumps(data["metadata"]),
            json.dumps(data["raw_data"]),
            json.dumps(data["results"]),
        ),
    )
    return cursor.fetchone()[0]


def main():
    parser = argparse.ArgumentParser(
        description=f"Commit {PROCESS_NAME} to database"
    )
    parser.add_argument("elab_id", type=int, help="eLabFTW experiment ID")
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Don't commit, just show what would be done",
    )
    parser.add_argument(
        "--init-schema-only",
        action="store_true",
        help="Only initialize process schema",
    )
    args = parser.parse_args()

    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        # Always upsert schema
        upsert_process_schema(cursor)
        print(
            "Process schema updated: {} (ID: {})".format(
                PROCESS_NAME, PROCESS_ID
            )
        )

        if args.init_schema_only:
            conn.commit()
            print("Schema-only mode, skipping experiment data.")
            return 0

        # Load experiment data
        exp_json_path = find_experiment_json(args.elab_id)
        with open(exp_json_path) as f:
            exp_data = json.load(f)

        # Extract fields
        extra_fields = exp_data.get("metadata_decoded", {}).get(
            "extra_fields", {}
        )
        workflow_json, lab_id = load_workflow()

        # Build data structures
        metadata = extract_metadata(extra_fields)
        raw_data = build_raw_data(args.elab_id)
        results = build_results(args.elab_id)

        status = (
            "completed"
            if results.get("analysis_status") in {"success", "failed"}
            else "pending"
        )

        data = {
            "title": exp_data.get("title", ""),
            "lab_id": lab_id,
            "status": status,
            "user": exp_data.get("userid_human", ""),
            "workflow_json": workflow_json,
            "metadata": metadata,
            "raw_data": raw_data,
            "results": results,
        }

        if args.dry_run:
            print("DRY RUN - Would insert:")
            print(json.dumps(data, indent=2, default=str))
            conn.rollback()
            return 0

        # Commit to database
        exp_db_id = upsert_experiment(cursor, args.elab_id, data)
        conn.commit()

        print(
            "Experiment {} committed successfully (DB ID: {})".format(
                args.elab_id, exp_db_id
            )
        )
        return 0

    except Exception as e:
        print("Error: {}".format(e), file=sys.stderr)
        if "conn" in locals():
            conn.rollback()
        return 1
    finally:
        if "conn" in locals():
            conn.close()


if __name__ == "__main__":
    sys.exit(main())
